function validate([eventTime, k, startTime, endTime]) {
  const n = startTime.length;
  if (eventTime < 1 || eventTime > 1000000000) return 'eventTime is between 1 and 10^9.';
  if (endTime.length !== n) return 'startTime and endTime need the same length.';
  if (n < 2 || n > 100000) return 'There are 2 to 10^5 meetings.';
  if (k < 1 || k > n) return 'k is between 1 and the number of meetings.';
  for (let i = 0; i < n; i++) {
    if (startTime[i] < 0 || startTime[i] >= endTime[i] || endTime[i] > eventTime) return 'Each meeting needs 0 <= startTime[i] < endTime[i] <= eventTime.';
    if (i + 1 < n && endTime[i] > startTime[i + 1]) return 'Meetings come in time order and do not overlap.';
  }
  return null;
}

