function maxFreeTime(eventTime, k, startTime, endTime) {
  const n = startTime.length;
  const gaps = [startTime[0]];
  for (let i = 1; i < n; i++) {
    gaps.push(startTime[i] - endTime[i - 1]);
  }
  gaps.push(eventTime - endTime[n - 1]);

  let windowSum = 0;
  let best = 0;
  for (let right = 0; right < gaps.length; right++) {
    windowSum += gaps[right];
    if (right > k) {
      windowSum -= gaps[right - k - 1];
    }
    if (right >= k) {
      best = Math.max(best, windowSum);
    }
  }
  return best;
}

