function maxFreeTime(eventTime, k, startTime, endTime) {
  // Try every set of at most k meetings to move. The meetings that stay split the event into stretches;
  // the moved meetings inside a stretch can be packed against one side, which frees the rest of it.
  const n = startTime.length;
  let best = 0;
  for (let mask = 0; mask < (1 << n); mask++) {
    let moved = 0;
    for (let i = 0; i < n; i++) if ((mask >> i) & 1) moved++;
    if (moved > k) continue;
    let stretchStart = 0, busy = 0;
    for (let i = 0; i <= n; i++) {
      if (i < n && ((mask >> i) & 1)) { busy += endTime[i] - startTime[i]; continue; }
      const stretchEnd = i < n ? startTime[i] : eventTime;
      best = Math.max(best, stretchEnd - stretchStart - busy);
      if (i < n) { stretchStart = endTime[i]; busy = 0; }
    }
  }
  return best;
}

