function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 2 + Math.floor(rand() * 7);
  // Small inputs sometimes use huge units so that values near 10^9 are exercised too.
  const unit = !large && rand() < 0.2 ? 1000000 : 1;
  const maxLength = large ? 200000 : 1 + Math.floor(rand() * 4);
  const maxGap = large ? 200000 : [0, 1, 3, 6][Math.floor(rand() * 4)];
  const gap = () => (rand() < 0.2 ? 0 : Math.floor(rand() * (maxGap + 1))) * unit;
  const startTime = [], endTime = [];
  let time = 0;
  for (let i = 0; i < n; i++) {
    time += gap();
    startTime.push(time);
    time += (1 + Math.floor(rand() * maxLength)) * unit;
    endTime.push(time);
  }
  const eventTime = time + gap();
  const k = rand() < 0.5 ? 1 + Math.floor(rand() * Math.min(n, large ? 20 : 2)) : 1 + Math.floor(rand() * n);
  return [eventTime, k, startTime, endTime];
}
